import re

with open(GRAPH_TTL, 'r', encoding='utf-8') as f:
    text = f.read()

# Find all point_uri -> tsref
# Pattern: bldg:XXX.YYY ... ;
#          ref:hasExternalReference <urn:buildgraph:tsref:UUID>
pair_pattern = re.compile(r'bldg:[\w.\[\]]+[^.;]*ref:hasExternalReference\s*<urn:buildgraph:tsref:[\w-]+>')
# Simpler: find blocks

# Use a different approach: split on lines and look for both in the same block (up to '.')
blocks = re.split(r'(?<!\w)\.\s*\n', text)
point_to_tsref = {}
tsref_to_id = {}

ts_block_pat = re.compile(r'<urn:buildgraph:tsref:([\w-]+)>\s*a\s+ref:TimeseriesReference\s*;\s*ref:hasTimeseriesId\s+"([\w-]+)"', re.DOTALL)
for m in ts_block_pat.finditer(text):
    tsref_to_id['urn:buildgraph:tsref:'+m.group(1)] = m.group(2)

# point to tsref
for blk in blocks:
    p_match = re.match(r'\s*bldg:([\w.\[\]]+)', blk)
    if not p_match:
        continue
    t_match = re.search(r'ref:hasExternalReference\s*<urn:buildgraph:tsref:([\w-]+)>', blk)
    if t_match:
        point_to_tsref['bldg:'+p_match.group(1)] = 'urn:buildgraph:tsref:'+t_match.group(1)

print("point_to_tsref count:", len(point_to_tsref))
print("tsref_to_id count:", len(tsref_to_id))

point_to_id = {}
for p, t in point_to_tsref.items():
    sid = tsref_to_id.get(t)
    if sid:
        point_to_id[p] = sid
print("point_to_id count:", len(point_to_id))

temp_points = {}
cooling_points = {}
heating_points = {}
for p, sid in point_to_id.items():
    local = p[5:]
    if local.endswith('.Zone_Air_Temperature_Sensor'):
        temp_points[local.split('.')[0]] = sid
    if local.endswith('.Zone_Air_Cooling_Temperature_Setpoint'):
        cooling_points[local.split('.')[0]] = sid
    if local.endswith('.Zone_Air_Heating_Temperature_Setpoint'):
        heating_points[local.split('.')[0]] = sid

both = sorted(set(temp_points) & set(cooling_points))
print("zones with both temp+cooling setpoint:", len(both))
print(both)

